import numpy as np

def epsilon_greedy(q_values, epsilon, rng=None):
    if not 0.0 <= epsilon <= 1.0:
        raise ValueError('epsilon must be between 0 and 1')
    rng = rng or np.random.default_rng()
    if rng.random() < epsilon:
        return int(rng.integers(len(q_values)))
    best_actions = np.flatnonzero(q_values == np.max(q_values))
    return int(rng.choice(best_actions))

values = np.array([1.0, 2.5, 2.5, 0.0])
print(epsilon_greedy(values, epsilon=0.1))

def linear_epsilon(step, start=1.0, end=0.05, decay_steps=10000):
    if decay_steps <= 0:
        return end
    fraction = min(max(step / decay_steps, 0.0), 1.0)
    return start + fraction * (end - start)

for step in [0, 2500, 5000, 10000, 15000]:
    print(step, linear_epsilon(step))

from collections import deque
import random

class ReplayBuffer:
    def __init__(self, capacity):
        self.data = deque(maxlen=capacity)

    def add(self, state, action, reward, next_state, terminated):
        self.data.append((state, action, reward, next_state, terminated))

    def sample(self, batch_size):
        if batch_size > len(self.data):
            raise ValueError('Not enough transitions to sample')
        return random.sample(self.data, batch_size)

    def __len__(self):
        return len(self.data)

buffer = ReplayBuffer(1000)
buffer.add(0, 1, 1.0, 1, False)
print('Stored transitions:', len(buffer))
